    {
      "citations": [
        {
          "event_id": "lite_evt_00022",
          "explanation": "Doctor did not independently decide surgical eligibility and tied it to preoperative results.",
          "quote": "这取决于术前检查结果"
        },
        {
          "event_id": "lite_evt_00137",
          "explanation": "Doctor explicitly deferred final readiness to anesthesia evaluation.",
          "quote": "等麻醉医生做最后的术前评估确认"
